/**
 * Merge platform/Info-additions.plist into the generated ios/Runner/Info.plist.
 *
 * `ios/` is not committed, for the same reason `android/` is not: lib/ is the
 * app and the native project is generated by `flutter create`, on a macOS
 * runner, once per build. The generated Info.plist has no location, camera or
 * photo strings, and iOS does not degrade gracefully without them -- asking for
 * the camera with no NSCameraUsageDescription kills the app on the spot, and
 * App Store review rejects a location request that does not say why.
 *
 * Idempotent: running it twice changes nothing.
 *
 * The development-only NSAppTransportSecurity block in the additions file is
 * commented out there, and stays out: a release build talks to https.
 */
import { existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'

const PLIST = 'ios/Runner/Info.plist'
const ADDITIONS = 'platform/Info-additions.plist'
const STOCK_TEST = 'test/widget_test.dart'

/* what sits under the app icon on the home screen; `flutter create` writes the
   project name title-cased, which reads "Autotracksa" */
const DISPLAY_NAME = 'أوتو تراك'

if (!existsSync(PLIST)) {
  console.error(`${PLIST}: not found -- run \`flutter create --platforms=ios .\` first`)
  process.exit(1)
}

let plist = readFileSync(PLIST, 'utf8')

/* The top-level dict closes on the last </dict> before </plist>. Everything is
   inserted there, so a key never lands inside a nested dict by accident. */
function insert(fragment) {
  const end = plist.lastIndexOf('</dict>')
  if (end < 0) {
    console.error(`${PLIST}: no closing </dict> -- not the shape flutter create emits`)
    process.exit(1)
  }
  plist = `${plist.slice(0, end)}${fragment}\n${plist.slice(end)}`
}

/* Each <key> in the additions file with the value element that follows it. The
   comments go first, so the commented-out ATS block cannot be picked up. */
const source = readFileSync(ADDITIONS, 'utf8').replace(/<!--[\s\S]*?-->/g, '')
const entries = [...source.matchAll(/<key>([^<]+)<\/key>\s*(<array>[\s\S]*?<\/array>|<dict>[\s\S]*?<\/dict>|<string>[\s\S]*?<\/string>|<true\/>|<false\/>)/g)]

if (!entries.length) {
  console.error(`${ADDITIONS}: no <key>/value pairs found`)
  process.exit(1)
}

const merged = []
for (const [, key, value] of entries) {
  if (plist.includes(`<key>${key}</key>`)) continue
  insert(`\t<key>${key}</key>\n\t${value.trim()}`)
  merged.push(key)
}
console.log(merged.length ? `merged ${merged.length} key(s): ${merged.join(', ')}` : 'Info.plist additions already present')

/* The name under the icon. Replaced rather than skipped when present, because
   flutter create always writes one and it is always the wrong one. */
const named = plist.replace(
  /(<key>CFBundleDisplayName<\/key>\s*<string>)[^<]*(<\/string>)/,
  `$1${DISPLAY_NAME}$2`,
)
if (named !== plist) {
  plist = named
  console.log(`set the display name to ${DISPLAY_NAME}`)
} else if (!plist.includes('<key>CFBundleDisplayName</key>')) {
  insert(`\t<key>CFBundleDisplayName</key>\n\t<string>${DISPLAY_NAME}</string>`)
  console.log(`added the display name ${DISPLAY_NAME}`)
}

/* The app only speaks HTTPS, which is exempt from US export rules. Declaring it
   here stops App Store Connect holding every TestFlight build at "Missing
   Compliance" until someone answers the same encryption question by hand. */
if (!plist.includes('<key>ITSAppUsesNonExemptEncryption</key>')) {
  insert('\t<key>ITSAppUsesNonExemptEncryption</key>\n\t<false/>')
  console.log('declared no non-exempt encryption')
}

writeFileSync(PLIST, plist)

/* Same stock counter test the Android script removes -- generation brings it
   back for every platform, and it does not compile against this app. */
if (existsSync(STOCK_TEST) && readFileSync(STOCK_TEST, 'utf8').includes('MyApp')) {
  rmSync(STOCK_TEST)
  console.log(`removed ${STOCK_TEST} -- the generated counter template`)
}
